#include <vector>
#include <functional>

long long countInversions(std::vector<int> a) {
    long long count = 0;

    std::function<std::vector<int>(std::vector<int>)> sortAndCount =
        [&](std::vector<int> arr) -> std::vector<int> {
        if (arr.size() <= 1) return arr;
        size_t mid = arr.size() / 2;
        auto left  = sortAndCount({arr.begin(), arr.begin() + mid});
        auto right = sortAndCount({arr.begin() + mid, arr.end()});

        std::vector<int> out;
        size_t i = 0, j = 0;
        while (i < left.size() && j < right.size()) {
            if (left[i] <= right[j]) {
                out.push_back(left[i++]);
            } else {
                // Every remaining left element is greater and earlier.
                count += (long long)(left.size() - i);
                out.push_back(right[j++]);
            }
        }
        while (i < left.size()) out.push_back(left[i++]);
        while (j < right.size()) out.push_back(right[j++]);
        return out;
    };

    sortAndCount(a);
    return count;
}
